<script setup lang="ts">
import {computed,onMounted,watch} from 'vue'
import {ArrowLeft,ArrowUpRight,ShoppingBag,Trash2,Undo2} from 'lucide-vue-next'
import {journey,loadJourney,loadBasket,saveChoice,removeChoice,detailFor,addChoice,importLegacyChoices,type Choice} from '../journey'
import {memoryEpoch} from '../voiceDraft'
const labels={scenic:'景区',food:'美食兴趣',place:'地点',poi:'园内看点',show:'演出场次',vendor:'具体商家',program:'演出项目'}
const removed=computed(()=>undo.value),undo=ref<Choice|null>(null)
import {ref} from 'vue'
async function remove(c:Choice){await removeChoice(c.key);if(!journey.choices.some(x=>x.key===c.key))undo.value={...c}}
async function restore(){if(undo.value){const restored=undo.value;await addChoice(restored);if(journey.choices.some(c=>c.key===restored.key))undo.value=null}}
watch(memoryEpoch,()=>undo.value=null)
async function change(c:Choice,patch:Partial<Choice>){await saveChoice({...c,...patch,source:'basket'})}
onMounted(()=>loadJourney(true))
</script>
<template><div class="page basket-page"><RouterLink to="/" class="back-link"><ArrowLeft :size="16"/>继续发现</RouterLink><header class="detail-section-title"><div><span class="tiny-caption">先收集，再安排</span><h1>旅行素材篮</h1></div><span class="basket-count">{{journey.choices.length}} 项</span></header><p v-if="journey.loading" class="state" role="status">正在读取素材篮…</p><div v-if="journey.error" class="error-state" role="alert">{{journey.error}}<button @click="loadJourney(true)">重试读取旅程</button></div><div v-if="journey.basketError" class="error-state" role="alert">{{journey.basketError}}<button @click="loadBasket">重试</button></div><button v-if="journey.legacyChoices.length" class="button secondary" type="button" :disabled="journey.basketBusy" @click="importLegacyChoices">将旧清单的 {{journey.legacyChoices.length}} 项导入这一程</button><section v-if="journey.choices.length" class="basket-items"><article v-for="c in journey.choices" :key="c.key" class="basket-item"><header><div><span class="tiny-caption">{{labels[c.kind]}} · {{c.status==='arranged'?'已安排':c.status==='standby'?'候补':'待安排'}}</span><h2><RouterLink :to="detailFor(c)">{{c.name}}<ArrowUpRight :size="15"/></RouterLink></h2></div><button type="button" :aria-label="'移出素材篮：'+c.name" :disabled="journey.basketBusy" @click="remove(c)"><Trash2 :size="17"/></button></header><div class="priority-segment" :aria-label="c.name+'优先级'"><button v-for="p in ([['must','必去'],['want','想去'],['optional','顺路看看']] as const)" :key="p[0]" type="button" :class="{active:c.priority===p[0]}" :aria-pressed="c.priority===p[0]" :disabled="journey.basketBusy" @click="change(c,{priority:p[0]})">{{p[1]}}</button></div><label class="basket-note">补充备注<input :key="c.updated_at" :value="c.note" maxlength="300" placeholder="例如：想多留些拍照时间" :disabled="journey.basketBusy" @change="change(c,{note:($event.target as HTMLInputElement).value})"></label><footer><small>{{c.fact_id?'已有业务资料，规划时仍会核验':'具体资料待添加'}}</small><button v-if="c.status!=='arranged'" type="button" :disabled="journey.basketBusy" @click="change(c,{status:c.status==='standby'?'pending':'standby'})">{{c.status==='standby'?'恢复待安排':'先放候补'}}</button></footer></article></section><div v-else-if="!journey.loading" class="journey-empty"><ShoppingBag :size="34" :stroke-width="1.2"/><h2>先收下一点心意</h2><p>在景点或美食旁点“加入素材篮”。</p><RouterLink class="button secondary" to="/">去发现开封</RouterLink></div><button v-if="removed" class="undo-basket" type="button" :disabled="journey.basketBusy" @click="restore"><Undo2 :size="15"/>撤销移除 {{removed.name}}</button><div v-if="journey.choices.length" class="basket-planning-cta"><RouterLink class="button primary" :to="{path:'/assistant',query:{city_trip:journey.trip?.id,plan:'basket'}}">交给小汴梁安排<ArrowUpRight :size="17"/></RouterLink><RouterLink class="text-link" to="/city-trip">查看行程</RouterLink></div></div></template>
